function reportPdfSections(title,subtitle,metrics,sections){const w=window.open('','_blank');if(!w){toast('Permita pop-ups para gerar o PDF.');return}const date=new Date().toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}),metricHtml=metrics.map(x=>`<div class="metric"><small>${esc(x.label)}</small><strong>${esc(x.value)}</strong></div>`).join(''),sectionsHtml=sections.map(section=>{const heads=section.headers.map(x=>`<th>${esc(x)}</th>`).join(''),body=section.rows.length?section.rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell??'—')}</td>`).join('')}</tr>`).join(''):`<tr><td class="empty" colspan="${section.headers.length}">Nenhum registro.</td></tr>`;return `<section class="report-section"><h2>${esc(section.title)}</h2>${section.note?`<p class="section-note">${esc(section.note)}</p>`:''}<table><thead><tr>${heads}</tr></thead><tbody>${body}</tbody></table></section>`}).join('');w.document.open();w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${esc(title)} - Giga Byte Telecom</title><style>@page{size:A4 landscape;margin:14mm 13mm 18mm}*{box-sizing:border-box}body{margin:0;color:#172536;font:9px Arial,sans-serif}.masthead{background:#10243a;color:white;padding:16px 20px;border-bottom:4px solid #29b6d1}.brand{font-size:16px;font-weight:800;letter-spacing:.5px}.brand-sub{margin-top:5px;color:#c1d2df;font-size:9px}.content{padding:18px 3px}.title-row{display:flex;justify-content:space-between;align-items:flex-start}.title{font-size:22px;font-weight:800;color:#10243a;margin:0 0 5px}.subtitle,.meta,.section-note{color:#68798a}.subtitle{font-size:10px}.badge{color:#1677c8;border:1px solid #bfdced;border-radius:20px;padding:6px 10px;font-size:8px;font-weight:700}.meta{margin:13px 0;font-size:8px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:12px 0 18px}.metric{border:1px solid #dce5ec;border-radius:7px;padding:10px;background:#f5f8fb}.metric small{display:block;color:#68798a;text-transform:uppercase;font-size:7px;font-weight:700}.metric strong{display:block;margin-top:5px;color:#10243a;font-size:16px}.report-section{margin:18px 0;break-inside:auto}.report-section h2{font-size:13px;color:#10243a;margin:0 0 6px;break-after:avoid-page}.section-note{font-size:8px;margin:0 0 7px}table{border-collapse:collapse;width:100%;table-layout:auto;margin-bottom:12px}thead{display:table-header-group}tr{break-inside:avoid;page-break-inside:avoid}th{background:#10243a;color:white;text-align:left;font-size:7px;text-transform:uppercase;padding:7px 6px}td{padding:6px;border-bottom:1px solid #dce5ec;vertical-align:top;font-size:7.6px;overflow-wrap:anywhere}tbody tr:nth-child(even){background:#f4f7fa}.empty{text-align:center;color:#68798a;padding:14px}.footer{position:fixed;bottom:-11mm;left:0;right:0;border-top:1px solid #dce5ec;padding-top:7px;color:#68798a;font-size:7px}@media print{.masthead,.metric,th{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><header class="masthead"><div class="brand">GIGA BYTE TELECOM</div><div class="brand-sub">CONTROLE INTERNO DE ESTOQUE E INSTALAÇÕES</div></header><main class="content"><div class="title-row"><div><h1 class="title">${esc(title)}</h1><div class="subtitle">${esc(subtitle)}</div></div><span class="badge">RELATÓRIO COMPLETO</span></div><div class="meta">Gerado em ${esc(date)} · Documento interno da equipe</div><section class="metrics">${metricHtml}</section>${sectionsHtml}<div class="footer"><strong>Giga Byte Telecom</strong> · Relatório consolidado · Confira os dados antes de compartilhar.</div></main><script>window.onload=()=>setTimeout(()=>window.print(),300)<\/script></body></html>`);w.document.close();w.focus()}
function exportCompleteReport(){const pending=state.queue.filter(x=>x.status!=='Concluído'),low=lowModels(),sumQty=items=>items.reduce((n,x)=>n+(Number(x.qty)||0),0),age=x=>Math.max(0,Math.floor((Date.now()-new Date(x.date||Date.now()).getTime())/86400000)),overview=[['Unidades de roteadores',sumQty(state.routers)],['Roteadores funcionando',sumQty(state.routers.filter(x=>x.condition==='Funcionando'))],['Roteadores em manutenção',sumQty(state.routers.filter(x=>x.condition==='Em manutenção'))],['Roteadores com defeito',sumQty(state.routers.filter(x=>x.condition==='Com defeito'))],['Status da contagem de fontes',state.sources.length?'Há quantidades registradas':'Aguardando contagem e cadastro no site'],['Quantidade informada de fontes',state.sources.length?sumQty(state.sources)+' unidades':'Não informada'],['Itens pendentes na fila',pending.length],['Unidades pendentes na fila',sumQty(pending)],['Itens concluídos na fila',state.queue.filter(x=>x.status==='Concluído').length],['Modelos abaixo do limite',low.length],['Movimentações registradas',state.moves.length],['Limite para alerta de estoque',state.minStock]];const stockRows=MODELS.map(m=>[m.brand,m.model,m.spec,stockFor(m.model),stockFor(m.model)===0?'Sem estoque':stockFor(m.model)<=state.minStock?'Repor':'Normal']);const routerRows=state.routers.map(x=>[x.brand,x.model,x.mac||'Não informado',x.qty,x.condition,x.system,x.location||'Não informado',x.registeredBy||'—',fmt(x.date),x.notes||'—']);const sourceRows=state.sources.length?state.sources.map(x=>[x.compatible||x.model||'—',x.qty,x.condition||'—',x.specs||'—',x.location||'—',fmt(x.date),x.notes||'—']):[['—','Não informada','Aguardando contagem','A quantidade ainda não foi informada no site.','—','—','—']];const queueRows=state.queue.map(x=>[x.brand||'—',x.model,x.mac||'Não informado',x.qty,x.status,x.owner||'Não atribuído',x.location||'Não informado',fmt(x.date),x.status==='Concluído'?'Concluído':age(x)+' dia(s)',x.notes||'—']);const moveRows=state.moves.map(x=>[fmt(x.date),x.type,x.brand||'—',x.model,x.qty,x.reason||'—',x.owner||'—']);[...low.map(x=>['Estoque baixo',`${x.brand} ${x.model}`,x.qty,'Limite: '+state.minStock,'Repor estoque']),...pending.map(x=>['Fila pendente',`${x.brand||''} ${x.model}`.trim(),x.qty,x.status,`${x.owner||'Sem responsável'} - ${age(x)} dia(s)`])];reportPdfSections('Relatório completo do inventário','Visão geral, saldos, equipamentos, fila, alertas e movimentações',[{label:'Unidades informadas',value:sumQty(state.routers)+sumQty(state.sources)},{label:'Roteadores',value:state.routers.length},{label:'Pendências abertas',value:pending.length},{label:'Alertas de estoque',value:low.length},{title:'2. Estoque por modelo',note:'Saldo consolidado por modelo; inclui alertas configurados pela equipe.',headers:['Marca','Modelo','Especificação','Quantidade','Situação'],rows:stockRows},{title:'3. Roteadores cadastrados',note:'Detalhes de sistema, condição, localização, responsável e observações.',headers:['Marca','Modelo','MAC','Qtd.','Condição','Sistema','Local','Cadastrado por','Data','Observações'],rows:routerRows},{title:'4. Fila de instalação',note:'Inclui itens pendentes e concluídos, com responsável e tempo de espera.',headers:['Marca','Modelo','MAC','Qtd.','Status','Responsável','Local','Entrada','Espera','Observações'],rows:queueRows},{title:'5. Fontes cadastradas',note:state.sources.length?'Quantidades informadas para os registros cadastrados no site.':'A contagem das fontes ainda não foi informada. O relatório não interpreta essa ausência como estoque zero.',headers:['Compatibilidade','Qtd.','Condição','Detalhes técnicos','Local','Data','Observações'],rows:sourceRows},{title:'6. Alertas e pendências',headers:['Tipo','Item','Qtd.','Situação','Ação / responsável'],rows:alertRows},{title:'7. Histórico de movimentações',headers:['Data','Tipo','Marca','Modelo','Qtd.','Motivo','Responsável'],rows:moveRows}])}
$('#exportQuick').textContent='↓ PDF completo';$('#exportQuick').onclick=exportCompleteReport;
window.addEventListener('offline',()=>{if(currentCredentials)setConnectionStatus('offline')});
window.addEventListener('online',()=>{if(currentCredentials){healthyPolls=0;connectionFailures=0;setConnectionStatus('unstable');checkConnection()}});
window.supabaseReady.then(client=>{supabaseClient=client;if(!window.backendReady)$('#loginMsg').textContent='Banco não configurado. Consulte CONFIGURAR-BANCO.md.';if(!client&&window.backendReady)$('#loginMsg').textContent='Serviço de banco indisponível. Verifique a conexão.'});
